import java.util.*;
import java.io.*;

public class Main {
    static final int N = 12;
    static final int INF = 1000000009;
    static final int[] dx = {0, 1, 0, -1};
    static final int[] dy = {1, 0, -1, 0};
    static int n, t;
    static char[][] gridA = new char[N][N];
    static char[][] gridB = new char[N][N];
    static int startX, startY;
    static int[][] dist = new int[N][N];

    static class Point {
        int x, y;
        Point() {}
        Point(int _x, int _y) {
            this.x = _x;
            this.y = _y;
        }
    }

    static void perform_bfs(int[][] dist_map, int sx, int sy) {
        boolean[][] visited = new boolean[N][N];
        for (int i = 0; i < n; ++i)
            Arrays.fill(dist_map[i], INF);
        Queue<Point> q = new LinkedList<>();
        visited[sx][sy] = true;
        dist_map[sx][sy] = 0;
        q.offer(new Point(sx, sy));
        while (!q.isEmpty()) {
            Point curr = q.poll();
            for (int dir = 0; dir < 4; ++dir) {
                int nx = curr.x + dx[dir];
                int ny = curr.y + dy[dir];
                if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny]
                        && gridA[nx][ny] >= '0' && gridA[nx][ny] <= '9') {
                    visited[nx][ny] = true;
                    dist_map[nx][ny] = dist_map[curr.x][curr.y] + 1;
                    q.offer(new Point(nx, ny));
                }
            }
        }
    }

    static boolean[][][][][] flow = new boolean[N * 6][N][N][N][N];
    static boolean[][][][] reachable = new boolean[N][N][N][N];

    static int[][] graph = new int[2 * N * N][2 * N * N];

    static int[] parent = new int[2 * N * N];
    static boolean[] visitedFlow = new boolean[2 * N * N];

    static boolean bfs_for_flow() {
        Arrays.fill(visitedFlow, false);
        Arrays.fill(parent, 0);
        Queue<Integer> q = new LinkedList<>();
        visitedFlow[0] = true;
        q.offer(0);
        while (!q.isEmpty()) {
            int node = q.poll();
            if (node == 2 * n * n + 1)
                return true;
            for (int h = 0; h <= 2 * n * n + 1; ++h) {
                if (graph[node][h] != 0) {
                    if (!visitedFlow[h]) {
                        visitedFlow[h] = true;
                        parent[h] = node;
                        q.offer(h);
                    }
                }
            }
        }
        return false;
    }

    static void solve() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        t = sc.nextInt();
        for (int i = 0; i < n; ++i)
            gridA[i] = sc.next().toCharArray();
        for (int i = 0; i < n; ++i)
            gridB[i] = sc.next().toCharArray();
        startX = sc.nextInt();
        startY = sc.nextInt();
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (gridA[i][j] == 'Z') {
                    startX = i;
                    startY = j;
                }

        perform_bfs(dist, startX, startY);

        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if ('0' <= gridA[i][j] && gridA[i][j] <= '9')
                    flow[0][i][j][i][j] = true;

        for (int step = 0; step < t; ++step) {
            for (int sx = 0; sx < n; ++sx)
                for (int sy = 0; sy < n; ++sy)
                    for (int x = 0; x < n; ++x)
                        for (int y = 0; y < n; ++y) {
                            if (!flow[step][sx][sy][x][y]) continue;
                            if (dist[x][y] <= step) continue;
                            for (int dir = 0; dir < 4; ++dir) {
                                int hx = x + dx[dir];
                                int hy = y + dy[dir];
                                if (hx >= 0 && hx < n && hy >= 0 && hy < n && '0' <= gridA[hx][hy] && gridA[hx][hy] <= '9') {
                                    if (dist[hx][hy] >= step + 1)
                                        flow[step + 1][sx][sy][hx][hy] = true;
                                }
                            }
                        }
        }

        for (int step = 0; step <= t; ++step)
            for (int sx = 0; sx < n; ++sx)
                for (int sy = 0; sy < n; ++sy)
                    for (int x = 0; x < n; ++x)
                        for (int y = 0; y < n; ++y)
                            if (flow[step][sx][sy][x][y])
                                reachable[sx][sy][x][y] = true;

        for (int x1 = 0; x1 < n; ++x1)
            for (int y1 = 0; y1 < n; ++y1)
                if ('0' <= gridA[x1][y1] && gridA[x1][y1] <= '9')
                    graph[0][x1 * n + y1 + 1] = gridA[x1][y1] - '0';

        for (int x2 = 0; x2 < n; ++x2)
            for (int y2 = 0; y2 < n; ++y2)
                if ('0' <= gridB[x2][y2] && gridB[x2][y2] <= '9')
                    graph[n * n + x2 * n + y2 + 1][2 * n * n + 1] = gridB[x2][y2] - '0';

        for (int x1 = 0; x1 < n; ++x1)
            for (int y1 = 0; y1 < n; ++y1)
                for (int x2 = 0; x2 < n; ++x2)
                    for (int y2 = 0; y2 < n; ++y2) {
                        if (!('0' <= gridA[x1][y1] && gridA[x1][y1] <= '9')) continue;
                        if (!('0' <= gridA[x2][y2] && gridA[x2][y2] <= '9')) continue;
                        if (!reachable[x1][y1][x2][y2]) continue;
                        graph[x1 * n + y1 + 1][n * n + x2 * n + y2 + 1] = INF;
                    }

        while (bfs_for_flow()) {
            int min_flow = INF;
            for (int i = 2 * n * n + 1; i != 0; i = parent[i]) {
                min_flow = Math.min(min_flow, graph[parent[i]][i]);
            }
            for (int i = 2 * n * n + 1; i != 0; i = parent[i]) {
                graph[parent[i]][i] -= min_flow;
                graph[i][parent[i]] += min_flow;
            }
        }

        int total_flow = 0;
        for (int i = 0; i <= 2 * n * n + 1; ++i)
            total_flow += graph[i][0];

        System.out.println(total_flow);
        sc.close();
    }

    public static void main(String[] args) {
        solve();
    }
}
